select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('section-code','کد بخش','text',true,10,'{}'),('section-title','عنوان بخش','text',true,20,'{}'),('page-code','کد صفحه','text',true,30,'{}'),('section-type','نوع بخش','select',true,40,'{"options":["هدر","منوی اصلی","قهرمان","محتوای اصلی","کارت‌ها","فهرست","فراخوان اقدام","فرم","اعلان","فوتر","سفارشی"]}'),('template-code','قالب بخش','text',false,50,'{}'),('block-reference','مرجع بلوک','text',false,60,'{}'),('order-index','ترتیب نمایش','number',true,70,'{}'),('visibility','سطح نمایش','select',true,80,'{"options":["عمومی","کاربران واردشده","نقش‌محور","سازمانی"]}'),('responsive-mode','رفتار ریسپانسیو','select',true,90,'{"options":["خودکار","موبایل‌محور","دسکتاپ‌محور","سفارشی"]}'),('status','وضعیت','select',true,100,'{"options":["پیش‌نویس","فعال","غیرفعال","آرشیو شده"]}'),('version','نسخه','number',true,110,'{}'),('content-reference','مرجع محتوا','text',false,120,'{}'),('notes','یادداشت','textarea',false,130,'{}')
) v(k,t,ft,r,s,o) where m.code='37-frontend-sections' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
