insert into platform_modules(code,title,is_active) values ('37-frontend-sections','مدیریت بخش‌های فرانت‌اند',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده بخش‌ها','modules:37-frontend-sections:read'),('write','ساخت و ویرایش بخش','modules:37-frontend-sections:write'),('delete','حذف بخش','modules:37-frontend-sections:delete'),('publish','فعال‌سازی بخش','modules:37-frontend-sections:publish'),('disable','غیرفعال‌سازی بخش','modules:37-frontend-sections:disable'),('duplicate','تکثیر بخش','modules:37-frontend-sections:duplicate'),('reorder','تنظیم ترتیب بخش','modules:37-frontend-sections:reorder')) v(a,t,p) where m.code='37-frontend-sections' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;